SELECT id, project_id, task_id, agent_id, model_name, input_tokens, output_tokens, total_tokens,
       user_id, session_id, source, create_time
FROM biz_token_usage
WHERE project_id = #{projectId}
ORDER BY id DESC
LIMIT #{limit}

SELECT id, project_id, task_id, agent_id, model_name, input_tokens, output_tokens, total_tokens,
       user_id, session_id, source, create_time
FROM biz_token_usage
WHERE task_id = #{taskId}
ORDER BY id DESC
LIMIT #{limit}
